import { WindowConf } from '@droid/android';
import { useProxyWatch, useTranslation } from '@fanfanlo';
import {
  Alert,
  Box,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { OptionalLabel, RequiredLabel } from './WindowConfUI';

export interface Step1BasicInfoProps {
  conf: WindowConf;
}

/**
 * Step 1: 基本信息
 *
 * 用户输入：
 * - tag: 窗口标识 (必填)
 * - description: 窗口说明 (可选)
 */
export function Step1BasicInfo({ conf }: Step1BasicInfoProps) {
  const { t } = useTranslation('homepage/components/android-float/window/content');

  const [tag] = useProxyWatch(conf, 'tag', conf.tag);
  const [description] = useProxyWatch(conf, 'description', conf.description || '');

  console.log('Step1BasicInfo: render tag:', tag);

  return (
    <Stack spacing={3}>
      <Typography variant="h6">{t('Step1BasicInfo.title')}</Typography>

      {/* 说明文字 */}
      <Alert severity="info">
        <Typography variant="body2">
          {t('Step1BasicInfo.description')}
        </Typography>
      </Alert>

      {/* 窗口标识 */}
      <Box>
        <RequiredLabel
          label={t('Step1BasicInfo.tagLabel')}
          description={t('Step1BasicInfo.tagDesc')}
        />
        <TextField
          value={tag}
          onChange={(e) => {
            console.log('Step1BasicInfo: tag changed to', e.target.value);
            conf.tag = e.target.value;
          }}
          placeholder={t('Step1BasicInfo.tagPlaceholder')}
          size="small"
          fullWidth
          helperText={t('Step1BasicInfo.tagHelper')}
        />
      </Box>

      {/* 窗口说明 */}
      <Box>
        <OptionalLabel
          label={t('Step1BasicInfo.descriptionLabel')}
          description={t('Step1BasicInfo.descriptionDesc')}
        />
        <TextField
          value={description}
          onChange={(e) => {
            console.log('Step1BasicInfo: description changed to', e.target.value);
            conf.description = e.target.value;
          }}
          placeholder={t('Step1BasicInfo.descriptionPlaceholder')}
          size="small"
          fullWidth
          multiline
          rows={3}
        />
      </Box>
    </Stack>
  );
}
