import { WindowConf, WindowType, createDefaultWindowConf, createDefaultFloatWindowConf } from '@droid/android';
import { toProxy, useTranslation, useProxyWatch } from '@fanfanlo';
import {
  Box,
  Button,
  Step,
  StepLabel,
  Stepper,
  Typography,
  Alert,
  Stack,
} from '@mui/material';
import { useState, useEffect } from 'react';
import { Step1BasicInfo } from './Step1BasicInfo';
import { Step2HtmlConf } from './Step2HtmlConf';
import { Step3WindowType } from './Step3WindowType';
import { Step4Advanced } from './Step4Advanced';

export interface WindowConfWizardProps {
  onComplete: (conf: WindowConf) => void;
  onCancel: () => void;
}

/**
 * WindowConfWizard - 分步引导创建窗口配置
 *
 * 4 个步骤：
 * 1. 基本信息 (窗口类型、标识、说明)
 * 2. HTML 内容 (URL 或 HTML 代码)
 * 3. 窗口特定配置 (根据窗口类型)
 * 4. 高级选项 (强制关闭时间、WebView 配置)
 */
export function WindowConfWizard({ onComplete, onCancel }: WindowConfWizardProps) {
  const { t } = useTranslation('homepage/components/android-float/window/content');

  const [step, setStep] = useState(1);
  const [conf] = useState(() => toProxy(createDefaultWindowConf()));
  const [errors, setErrors] = useState<Record<string, string>>({});

  // 监听 windowType 变化，使用 useProxyWatch
  const [windowType] = useProxyWatch(conf, 'windowType', conf.windowType);

  console.log('WindowConfWizard: render step', step);

  /**
   * 监听 windowType 变化，初始化对应的窗口配置
   */
  useEffect(() => {
    console.log('WindowConfWizard: useEffect - windowType changed to', windowType);

    // 仅保留 Float 窗口配置
    if (windowType === WindowType.Float) {
      console.log('WindowConfWizard: initializing floatWindowConf');
      conf.floatWindowConf = createDefaultFloatWindowConf();
    }
  }, [windowType, conf]);

  /**
   * 验证当前步骤的必填字段
   */
  const validateStep = (currentStep: number): boolean => {
    console.log('WindowConfWizard: validateStep', currentStep);

    switch (currentStep) {
      case 1:
        // Step 1: tag 必填
        const isStep1Valid = conf.tag.trim() !== '';
        console.log('WindowConfWizard: Step 1 validation - tag:', conf.tag, 'valid:', isStep1Valid);
        return isStep1Valid;

      case 2:
        // Step 2: url 和 html 必须二选一
        const url = (conf.htmlConf?.url || '').trim();
        const html = (conf.htmlConf?.html || '').trim();
        const isStep2Valid = url !== '' || html !== '';
        console.log('WindowConfWizard: Step 2 validation - url:', url, 'html:', html, 'valid:', isStep2Valid);
        return isStep2Valid;

      case 3:
        // Step 3: 仅验证 floatWindowConf
        const isStep3Valid = conf.floatWindowConf !== undefined;
        console.log('WindowConfWizard: Step 3 validation - valid:', isStep3Valid);
        return isStep3Valid;

      case 4:
        // Step 4: 无强制验证
        console.log('WindowConfWizard: Step 4 validation - no validation required');
        return true;

      default:
        return true;
    }
  };

  /**
   * 处理下一步
   */
  const handleNext = () => {
    console.log('WindowConfWizard: handleNext called, current step:', step);

    if (validateStep(step)) {
      console.log('WindowConfWizard: validation passed');
      if (step < 4) {
        setStep(step + 1);
      } else {
        console.log('WindowConfWizard: calling onComplete');
        onComplete(conf);
      }
      setErrors({});
    } else {
      console.log('WindowConfWizard: validation failed');
      setErrors({ ...errors, [step]: t('WindowConfWizard.validationError') || '请填写所有必填项' });
    }
  };

  /**
   * 处理上一步
   */
  const handlePrevious = () => {
    console.log('WindowConfWizard: handlePrevious called, current step:', step);
    if (step > 1) {
      setStep(step - 1);
      setErrors({});
    }
  };

  /**
   * 处理取消
   */
  const handleCancel = () => {
    console.log('WindowConfWizard: calling onCancel');
    onCancel();
  };

  return (
    <Box sx={{ p: 3 }}>
      {/* Stepper - 进度条 */}
      <Stepper activeStep={step - 1} sx={{ mb: 4 }}>
        <Step>
          <StepLabel>{t('WindowConfWizard.basicInfo')}</StepLabel>
        </Step>
        <Step>
          <StepLabel>{t('WindowConfWizard.htmlContent')}</StepLabel>
        </Step>
        <Step>
          <StepLabel>{t('WindowConfWizard.windowConfig')}</StepLabel>
        </Step>
        <Step>
          <StepLabel>{t('WindowConfWizard.advancedOptions')}</StepLabel>
        </Step>
      </Stepper>

      {/* 错误提示 */}
      {errors[step] && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {errors[step]}
        </Alert>
      )}

      {/* Step 内容 */}
      <Box sx={{ minHeight: 400, mb: 3 }}>
        {step === 1 && <Step1BasicInfo conf={conf} />}
        {step === 2 && <Step2HtmlConf conf={conf} />}
        {step === 3 && <Step3WindowType conf={conf} />}
        {step === 4 && <Step4Advanced conf={conf} />}
      </Box>

      {/* 页脚按钮 */}
      <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end' }}>
        <Button onClick={handleCancel}>{t('WindowConfWizard.cancel')}</Button>
        <Button disabled={step === 1} onClick={handlePrevious}>
          {t('WindowConfWizard.previousStep')}
        </Button>
        <Button variant="contained" onClick={handleNext}>
          {step === 4 ? t('WindowConfWizard.completeCreate') : t('WindowConfWizard.nextStep')}
        </Button>
      </Box>
    </Box>
  );
}
