import { WindowConf } from '@droid/android';
import { useProxyWatch, useTranslation } from '@fanfanlo';
import { Alert, Box, Stack, TextField, Typography } from '@mui/material';
import { OptionalLabel } from './WindowConfUI';
import { WebViewConfUI } from './WindowConfUI';

export interface Step4AdvancedProps {
  conf: WindowConf;
}

/**
 * Step 4: 高级选项
 *
 * 配置：
 * - forceDismissWindowTime: 强制关闭时间
 * - WebViewConf: WebView 配置
 * - 显示完成总结
 */
export function Step4Advanced({ conf }: Step4AdvancedProps) {
  const [forceDismissWindowTime] = useProxyWatch(
    conf,
    'forceDismissWindowTime',
    conf.forceDismissWindowTime
  );
  const [htmlConf] = useProxyWatch(conf, 'htmlConf', conf.htmlConf);
  const [tag] = useProxyWatch(conf, 'tag', conf.tag);

  const { t } = useTranslation('homepage/components/android-float/window/content');
  console.log('Step4Advanced: render forceDismissWindowTime:', forceDismissWindowTime);

  return (
    <Stack spacing={3}>
      <Typography variant="h6">{t('Step4Advanced.title')}</Typography>

      {/* 说明文字 */}
      <Alert severity="info">
        <Typography variant="body2">
          {t('Step4Advanced.description')}
        </Typography>
      </Alert>

      {/* 强制关闭时间 */}
      <Box>
        <OptionalLabel
          label={t('Step4Advanced.dismissTimeLabel')}
          description={t('Step4Advanced.dismissTimeDesc')}
        />
        <TextField
          type="number"
          value={forceDismissWindowTime}
          onChange={(e) => {
            console.log('Step4Advanced: forceDismissWindowTime changed to', e.target.value);
            conf.forceDismissWindowTime = Number(e.target.value);
          }}
          size="small"
          fullWidth
          inputProps={{ min: 0, step: 1000 }}
        />
        <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
          {t('Step4Advanced.dismissTimeHelper')}
        </Typography>
      </Box>

      {/* WebView 配置 */}
      {htmlConf?.webViewConf && (
        <Box>
          <Typography variant="subtitle2" sx={{ fontWeight: 'bold', color: 'primary.main', mb: 2 }}>
            {t('Step4Advanced.webViewConfig')}
          </Typography>
          <WebViewConfUI webViewConf={htmlConf.webViewConf} />
        </Box>
      )}

      {/* 完成总结 */}
      <Box sx={{ p: 2, bgcolor: 'success.light', borderRadius: 1 }}>
        <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 1 }}>
          {t('Step4Advanced.completeSummary')}
        </Typography>
        <Stack spacing={0.5} sx={{ fontSize: '0.875rem' }}>
          <Typography variant="body2">
            <strong>{t('Step4Advanced.summaryTag')}</strong> {tag}
          </Typography>
          <Typography variant="body2">
            <strong>{t('Step4Advanced.summaryType')}</strong> {conf.windowType}
          </Typography>
          <Typography variant="body2">
            <strong>{t('Step4Advanced.summaryUrl')}</strong> {htmlConf?.url || '(未设置)'}
          </Typography>
          {htmlConf?.html && (
            <Typography variant="body2">
              <strong>{t('Step4Advanced.summaryHtml')}</strong> {htmlConf.html.substring(0, 50)}...
            </Typography>
          )}
        </Stack>
      </Box>
    </Stack>
  );
}
